import{_ as a,o as s,c as i,a0 as t}from"./chunks/framework.l1I-fhud.js";const k=JSON.parse(`{"title":"How to put a package's binaries on your PATH","description":"","frontmatter":{},"headers":[],"relativePath":"how-to/link-binaries.md","filePath":"how-to/link-binaries.md"}`),n={name:"how-to/link-binaries.md"};function o(l,e,r,d,c,h){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="how-to-put-a-package-s-binaries-on-your-path" tabindex="-1">How to put a package&#39;s binaries on your PATH <a class="header-anchor" href="#how-to-put-a-package-s-binaries-on-your-path" aria-label="Permalink to &quot;How to put a package&#39;s binaries on your PATH&quot;">​</a></h1><p>A package payload may ship a <code>bin/</code> directory of executables — release tarballs installed from <code>https://…#sha256:…</code> refs use this layout (see the binary-distribution ADR). <code>install</code> unpacks the payload into the store; <strong><code>tamias bin</code></strong> is the verb that makes those executables runnable by bare name — for your shell and for provider <code>services[].exec</code>.</p><h2 id="link-a-package-s-binaries" tabindex="-1">Link a package&#39;s binaries <a class="header-anchor" href="#link-a-package-s-binaries" aria-label="Permalink to &quot;Link a package&#39;s binaries&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tamias</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;https://github.com/9aia/tamias/releases/download/v0.1.2/tamias-x86_64-unknown-linux-gnu.tar.gz#sha256:…&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tamias</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tamias</span></span></code></pre></div><p><code>tamias bin &lt;name&gt;</code> accepts <code>@scope/name</code> or a bare <code>name</code>, and links every regular file directly under the package&#39;s <code>bin/</code> (dotfiles and nested dirs are skipped) into the bin dir:</p><ul><li><code>$TAMIAS_BIN_DIR</code>, else <code>$XDG_BIN_HOME</code>, else <code>~/.local/bin</code>.</li></ul><p>Each link prints as it is made; <code>--json</code> emits the same data as JSON.</p><h2 id="why-links-survive-upgrades" tabindex="-1">Why links survive upgrades <a class="header-anchor" href="#why-links-survive-upgrades" aria-label="Permalink to &quot;Why links survive upgrades&quot;">​</a></h2><p>Store entry dirs are versioned (<code>name@&lt;version&gt;</code> or a sha label) and a new version installs to a <em>new</em> dir — a link aimed at the raw entry dir would dangle after <code>tamias update</code>. Instead <code>tamias bin</code> keeps a stable per-name <strong>alias</strong> — <code>bin-alias/&lt;name&gt;</code> as a sibling of the store root (<code>~/.local/share/tamias/bin-alias</code> by default, <code>$TAMIAS_HOME/bin-alias</code> under <code>TAMIAS_HOME</code>) pointing at the current entry dir — and links <code>&lt;bin&gt;/&lt;file&gt;</code> → <code>&lt;alias&gt;/bin/&lt;file&gt;</code>. Installs and updates retarget the alias automatically when it exists, so existing links keep resolving. Re-run <code>tamias bin &lt;name&gt;</code> after an upgrade that <em>adds</em> or <em>renames</em> binaries — the alias follows, but new payload files need a fresh link pass.</p><p>On Unix the links are symlinks. On Windows — where symlink creation needs privileges — the payload file is <strong>copied</strong> instead; re-run <code>tamias bin</code> after upgrades to refresh stale copies (<code>--force</code> also works).</p><h2 id="conflicts-and-removal" tabindex="-1">Conflicts and removal <a class="header-anchor" href="#conflicts-and-removal" aria-label="Permalink to &quot;Conflicts and removal&quot;">​</a></h2><p><code>tamias bin</code> refuses to overwrite anything already at a link path — a foreign file, a foreign symlink, even a directory — unless <code>--force</code> is passed. A link <code>tamias bin</code> already made is idempotent: re-running reports <code>already linked</code> and changes nothing.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tamias</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tamias</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --unlink</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # remove this package&#39;s links + alias</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tamias</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tamias</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # take over conflicting paths</span></span></code></pre></div><p><code>--unlink</code> removes the bin-dir entries the package owns — links into its alias, plus byte-identical copies on copy platforms — and drops the alias itself. It never touches files that don&#39;t belong to the package. <code>tamias remove</code> and <code>tamias uninstall</code> run the same cleanup automatically once the store entry is dropped, so links don&#39;t dangle; <code>--unlink</code> remains the verb for unlinking while the package stays installed. Provider services that named the bare binary keep working until the links go away; after that, update their <code>exec:</code> to a full path or reinstall the binaries.</p><h2 id="upgrading-the-binary-you-re-running" tabindex="-1">Upgrading the binary you&#39;re running <a class="header-anchor" href="#upgrading-the-binary-you-re-running" aria-label="Permalink to &quot;Upgrading the binary you&#39;re running&quot;">​</a></h2><p><code>tamias update &lt;name&gt;</code> upgrades a package, but the <em>running</em> executable can&#39;t replace itself — a process keeps its old inode even after the store entry swaps. <strong><code>tamias self-upgrade</code></strong> closes that loop for tamias-managed binaries: it detects that the running exe resolves into the store (directly, or through the <code>bin-alias</code>/bin-dir link chain — a cargo or distro install fails with &quot;not installed via tamias&quot;), then re-installs the package&#39;s recorded source ref, exactly like <code>tamias update</code>. The install retargets the alias, so the <em>next</em> invocation runs the new version; this process keeps the old one — restart to pick it up.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tamias</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> self-upgrade</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --check</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # current vs what the ref resolves to</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                              # — no install, fetches to the cache only</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tamias</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> self-upgrade</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # update + retarget the alias</span></span></code></pre></div><p>A release install pinned to a <code>#sha256:</code> ref re-fetches exactly those bytes; a moving ref (branch, <code>latest</code>) re-resolves. <code>--allow-drivers</code> and <code>--json</code> behave as they do for <code>install</code>/<code>update</code>. On Windows — where <code>tamias bin</code> copies rather than symlinks — the running exe file can be locked; self-upgrade warns before attempting and you may need to close other tamias processes and retry.</p><h2 id="errors-you-ll-see" tabindex="-1">Errors you&#39;ll see <a class="header-anchor" href="#errors-you-ll-see" aria-label="Permalink to &quot;Errors you&#39;ll see&quot;">​</a></h2><ul><li><code>package &#39;x&#39; is not installed</code> — install it first (<code>tamias install</code>).</li><li><code>&lt;label&gt;: no bin/ payload — nothing to link</code> — the package ships no <code>bin/</code> directory (or it&#39;s empty); nothing to do.</li><li><code>&lt;path&gt; already exists — refusing to overwrite (use --force)</code> — something else owns the link path.</li><li><code>… is not a tamias-managed binary</code> (<code>self-upgrade</code>) — the running exe wasn&#39;t installed via tamias; use your package manager or <code>cargo install</code> instead.</li></ul>`,20)])])}const g=a(n,[["render",o]]);export{k as __pageData,g as default};
